Ltac zcallA Z0SPEC hp HSp ZC OXC spo lo slo :=
  let SP := fresh "SP" in
  pose proof Z0SPEC as SP; unfold mpi_cmp_int_z0_stmtA in SP;
  specialize (SP hp); rewrite (proj1 HSp) in SP; unfold mpi_cmp_int_postA in SP;
  callrt spo
    (eapply SP with (lo := lo) (slo := slo); rewrite ?(unsigned_lit spo) by lia;
     first [ exact ZC | exact OXC | eassumption | reflexivity
           | (destruct HSp as (_ & ?EH & _); lia)
           | match goal with CRx : client_range _ _ lo ?Cx _ |- client_range _ _ lo _ _ =>
               unfold client_range in CRx |- *; intros ?a ?Ha; apply CRx; lia end
           | lia | match goal with |- ?g => idtac "ZCALL-LEFT:" g end ]);
  clear SP.

Tactic Notation "cpl_post" constr(hp) constr(HSp) ident(hn) ident(HSn) :=
  lazymatch goal with H : presA _ _ _ _ _ _ _ _ ?ma ?mb |- _ =>
    let HP := fresh "HPc" in rename H into HP;
    lazymatch goal with HHx : HM _ _ _ ?hh _ _ mb |- _ => rename hh into hn end;
    pose proof (ck_hsame_trans _ _ _ hn hp _ ltac:(unfold ck_hsame; do 6 (split; [assumption|]); assumption) HSp) as HSn;
    try rewrite (proj1 (proj2 (proj2 HSp))) in HP;
    presA_transport HP; clear HP;
    repeat lazymatch goal with Hx : HM _ _ _ _ _ _ ma |- _ => clear Hx end;
    repeat lazymatch goal with Hx : stk _ ma _ _ |- _ => clear Hx end
  end.

