Theorem A_rsa_complete_spec : forall (R : art_layout) (HIA : artA asegs R),
    asan_img_ok (arl_AL R) -> arl_uar_got R = A_UAR_GOT_CI -> arl_smalloc R 0 = A_SMALLOC_0_CI ->
    0 <= arl_need_smalloc R ->
    rsa_complete_stmtA asegs R HIA A_RSA_COMPLETE.
Proof.
  intros R HIA IMG UG SM0 NS0. unfold rsa_complete_stmtA, A_RSA_COMPLETE. intros until slo.
  intros HH LFB RA_ SGN SGE PN PE ST SLOS SLO SLO2 TOP SPA TPV SSH SSL1 SSL2 MI RA OC ON OE CRC DC DN DE ->. unfold RSA_CTX_SIZE in OC, DC, CRC.
  pose proof (art_alwf asegs R HIA) as ALWF. pose proof (hcs_ok asegs R HIA h) as CSOK. pose proof (hm_abase asegs R HIA h LB LF m HH) as AB.
  pose proof (cs_ok_sb _ _ CSOK) as SB64. pose proof ALWF as ALWF'; unfold al_wf in ALWF'. pose proof IMG as IMG'; unfold asan_img_ok in IMG'.
  pose proof (bv_unsigned_in_range 64 sp) as SPB. change (bv_modulus 64) with (2^64) in SPB.
  pose proof (hm_top asegs R HIA h LB LF m HH) as HTOP. pose proof (art_lo asegs R HIA) as ALO.
  assert (LO0 : 0 <= lo) by (pose proof (@alloc_ceiling_pos (arl_L R)); lia).
  assert (SCS : crange (hcs asegs R HIA h) lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact (hcs_stack asegs R HIA h)| lia| lia]).
  pose proof (presW_init asegs R HIA h LB LF m (bv_unsigned sp) (arl_stklo R) [] HH ltac:(lia)) as PW.
  pose proof (ck_hsame_refl asegs R HIA h) as HS0.
  pose proof (hm_wlow asegs R HIA h LB LF m HH) as WL.
  assert (SCSS : crange (hcs asegs R HIA h) slo (bv_unsigned sp - slo)) by (eapply crange_sub; [exact (hcs_stack asegs R HIA h)| lia| lia]).
  assert (CRC192 : client_range (arl_L R) (LB ++ fdata LF) (bv_unsigned sp + -192) C RSA_CTX_SIZE).
  { unfold RSA_CTX_SIZE, client_range, client_addr in *. intros a Ha. destruct DC as [DC'|DC']; [| left; lia].
    destruct (CRC a Ha) as [X|X]; [lia| right; exact X]. }
  assert (CRCs : client_range (arl_L R) (LB ++ fdata LF) (bv_unsigned sp) C RSA_CTX_SIZE).
  { unfold RSA_CTX_SIZE, client_range, client_addr in *. intros a Ha. destruct DC as [DC'|DC']; [| left; lia].
    destruct (CRC a Ha) as [X|X]; [lia| right; exact X]. }
  unfold RSA_CTX_SIZE in CRC192, CRCs.
  assert (CRC48 : client_range (arl_L R) (LB ++ fdata LF) lo C 48) by (unfold client_range in CRC |- *; intros a Ha; apply CRC; lia).
  ddestruct RA_ as (HD & HT & AN & AE & [NSN _] & [NSE _] & LEN & ALL & CAL & C0 & CB & _).
  pose proof CB as CB'; unfold RSA_CTX_SIZE in CB'.
  assert (MN : mpd_at asegs m LB (r_N r)) by (split; [exact (Forall_inv ALL)| lia]).
  assert (ME : mpd_at asegs m LB (r_E r)) by (split; [exact (Forall_inv (Forall_inv_tail ALL))| lia]).
  pose proof (Forall_inv_tail (Forall_inv_tail ALL)) as ZS. clear ALL.
  unfold rsa_zero_mpds, rsa_zero_offs in ZS. cbn [map] in ZS.
